  "😤 НУ ДАВАЙ, ЗАПЛАЧЬ!!!\n\nТренировка на {p}% хуже обычного:": "😤 НУ ДАВАЙ, ЗАПЛАЧ!!!\n\nТренування на {p}% гірше, ніж зазвичай:",
