  "Готово! ✅ Анкета сохранена.\nЯ буду присылать итоги тренировок, утренние напоминания о зарядке и иногда спрашивать про активность. Выключить напоминания — /reminders": "Done! ✅ Form saved.\nI'll send you workout summaries, morning reminders to warm up, and sometimes ask about your activity. Turn off reminders — /reminders",
