  "Кто может видеть ваши данные (возраст, пол, вес, рост, цель)?\nПо умолчанию — только вы. Изменить можно в приложении: Участники → вы → «Личные данные».": "Who can see your data (age, gender, weight, height, goal)?\nBy default — only you. You can change this in the app: Members → you → «Personal data».",
