  "📨 Сертификат «{name}» отправлен на проверку. Как только администратор его посмотрит, я напишу — он появится в «Достижениях → Соревнования».": "📨 Your certificate “{name}” has been sent for review. I’ll message you as soon as an admin checks it — it will appear in “Achievements → Competitions”.",
  "🛡️ Открыть админ-панель": "🛡️ Open admin panel",
  "🎖️ Вам выдана персональная ачивка!": "🎖️ You've received a personal achievement!",
  "📦 Резервная копия дневника. Сохраните файл: на новом устройстве или аккаунте откройте Настройки → «Загрузить из файла».": "📦 Diary backup. Save this file: on a new device or account open Settings → “Load from file”.",
  "Привет, {name}! 👋\n\nЭто <b>GymDiary</b> — дневник тренировок прямо в Telegram.\n\n🏋️ Записывайте подходы, веса и повторы — тоннаж, рекорды и прогресс посчитаются сами.\n🏆 Получайте ачивки и постеры «Light weight, baby!» за личные рекорды.\n🍽 Считайте калории и БЖУ — больше 2000 продуктов и блюд.\n👥 Тренируйтесь с друзьями и тренером: он видит ваши тренировки и питание, если вы разрешите.\n📊 Итоги тренировок, недели и месяца, утренняя зарядка — я пришлю сюда.\n\nСначала 6 коротких вопросов — это минута. Ответы видите только вы, пока сами не решите иначе.": "Hi, {name}! 👋\n\nThis is <b>GymDiary</b> — a workout diary right inside Telegram.\n\n🏋️ Log sets, weights and reps — tonnage, PRs and progress are calculated automatically.\n🏆 Earn achievements and “Light weight, baby!” posters for your personal records.\n🍽 Track calories and macros — over 2000 foods and dishes.\n👥 Train with friends and a coach: your coach sees your workouts and nutrition if you allow it.\n📊 Workout, weekly and monthly summaries plus morning exercises — I’ll send them here.\n\nFirst, 6 quick questions — it takes a minute. Only you can see your answers unless you decide otherwise.",
  "Дневник тренировок: подходы, тоннаж, рекорды, ачивки, калории и тренер — прямо в Telegram 💪": "Workout diary: sets, tonnage, PRs, achievements, calories and a coach — right in Telegram 💪",
  "GymDiary — дневник тренировок прямо в Telegram.\n\n• Подходы, веса и повторы: тоннаж, рекорды и прогресс считаются сами.\n• Сотни ачивок и постеры «Light weight, baby!» за личные рекорды.\n• Калории и БЖУ: больше 2000 продуктов и блюд.\n• Тренер видит тренировки и питание подопечных, друзья — ваши ачивки.\n• Итоги тренировок, недели и месяца и утренняя зарядка — от бота.\n\nНажмите «Запустить» 👇": "GymDiary — a workout diary right inside Telegram.\n\n• Sets, weights and reps: tonnage, PRs and progress are calculated automatically.\n• Hundreds of achievements and “Light weight, baby!” posters for personal records.\n• Calories and macros: over 2000 foods and dishes.\n• Coaches see their clients’ workouts and nutrition; friends see your achievements.\n• Workout, weekly and monthly summaries and morning exercises — from the bot.\n\nTap “Start” 👇"
