  "Готово! ✅ Анкета сохранена.\nЯ буду присылать итоги тренировок, утренние напоминания о зарядке и иногда спрашивать про активность. Выключить напоминания — /reminders": "C'est fait ! ✅ Questionnaire enregistré.\nJe t'enverrai les bilans d'entraînement, des rappels matinaux pour t'échauffer et je te demanderai parfois comment ça va côté activité. Désactiver les rappels — /reminders",
