  "Доброе утро! Вращения плечами и наклоны в стороны — по 10–15 повторений в каждую сторону 💪": "Bonjour ! Rotations d'épaules et flexions latérales — 10 à 15 répétitions de chaque côté 💪",
  "Доброе утро! Выпады — по 8 на каждую ногу. Спокойно, без рывков.": "Bonjour ! Fentes — 8 par jambe. Calmement, sans à-coups.",
  "Доброе утро! Наклон вперёд: тянемся к носкам 20 секунд, колени мягкие.": "Bonjour ! Flexion avant : on étire vers les orteils 20 secondes, genoux souples.",
  "Доброе утро! Планка 30 секунд: живот подтянут, спина ровная ⏱": "Bonjour ! Gainage 30 secondes : ventre contracté, dos droit ⏱",
  "Доброе утро! Шаг на месте 1 минуту, колени высоко — разгоняем пульс 👟": "Bonjour ! Marche sur place 1 minute, genoux hauts — on relance le rythme cardiaque 👟",
  "Доброе утро! ☀️ Потянись: руки вверх и 5 глубоких вдохов — тело просыпается.": "Bonjour ! ☀️ Étire-toi : bras en l'air et 5 respirations profondes — le corps se réveille.",
  "Другое": "Autre",
