  "Заполните возраст, пол, рост и вес в личных данных — я посчитаю вашу норму и подскажу, всё ли в порядке.": "Renseignez votre âge, sexe, taille et poids dans vos données personnelles — je calculerai vos besoins et vous dirai si tout va bien.",
