  "Кошка-корова 10–15 плавных повторов — спина будет благодарна весь день 🐱🐮": "Chat-vache, 10 à 15 répétitions lentes — le dos te remerciera toute la journée 🐱🐮",
  "Кто может видеть ваши данные (возраст, пол, вес, рост, цель)?\nПо умолчанию — только вы. Изменить можно в приложении: Участники → вы → «Личные данные».": "Qui peut voir vos données (âge, sexe, poids, taille, objectif) ?\nPar défaut — seulement vous. Modifiable dans l'application : Participants → vous → « Données personnelles ».",
  "Лучшая тренировка — та, которая состоялась. Даже лёгкая. Погнали? 🔥": "Le meilleur entraînement, c'est celui qui a lieu. Même léger. On y va ? 🔥",
  "Лучшая тренировка: {name} {date} — {v} кг": "Meilleur entraînement : {name} {date} — {v} kg",
