  "Напишите возраст числом, например: 29": "Indiquez votre âge en chiffres, par exemple : 29",
  "Напишите количество шагов числом, например: 12000": "Indiquez le nombre de pas, par exemple : 12000",
  "Напишите рост в сантиметрах, например: 178": "Indiquez votre taille en centimètres, par exemple : 178",
