  "Не залипай в телефон — вставай! Шаг на месте 1 минуту, колени высоко.": "Ne reste pas scotché à ton téléphone — lève-toi ! Marche sur place 1 minute, genoux hauts.",
  "Небольшая цель на сегодня: 15 минут движения. Справишься? Уверен, что да!": "Petit objectif pour aujourd'hui : 15 minutes de mouvement. Tu peux le faire ? Sûr et certain !",
