  "Подъём! 30 «джампинг-джеков» — и кровь побежала быстрее 🔥": "Debout ! 30 « jumping jacks » — et le sang circule plus vite 🔥",
  "Помнишь, зачем ты начинал? Один шаг — одна тренировка. Сегодня отличный день, чтобы вернуться!": "Tu te souviens pourquoi tu as commencé ? Un pas à la fois, un entraînement à la fois. Aujourd'hui, c'est le jour idéal pour reprendre !",
  "Понял. Отдых тоже часть прогресса 😌 Завтра — новый день!": "Compris. Le repos fait aussi partie du progrès 😌 Demain, nouveau jour !",
