  "Пресс": "Abdos",
  "Привет, {name}! 👋 Я бот «ТренДневника».\nЗадам 6 коротких вопросов — это займёт минуту. Эти данные видите только вы, пока сами не решите иначе.": "Salut, {name} ! 👋 Je suis le bot « GymDiary ».\nJe vais te poser 6 courtes questions — ça prendra une minute. Ces données ne sont visibles que par toi, sauf si tu décides autrement.",
