  "Прогресс есть — так держать! 🔥": "Il y a des progrès — continue comme ça ! 🔥",
  "Прогресс любит регулярность. Два дня отдыха были, пора снова в бой 🏋️": "Le progrès aime la régularité. Deux jours de repos, c'est fait, il est temps de repartir au combat 🏋️",
