  "❌ Часть картинок недоступна — проверьте, что папки img/ и bot/ запушены и MINI_APP_URL указывает на адрес приложения.": "❌ Certaines images sont indisponibles — vérifiez que les dossiers img/ et bot/ sont bien poussés et que MINI_APP_URL pointe vers l'adresse de l'application.",
  "🍽 <b>Питание за день</b> ({date})": "🍽 <b>Alimentation du jour</b> ({date})",
  "🍽 {who} изменил(а) записи в своём дневнике питания, которые вносили вы:": "🍽 {who} a modifié dans son propre journal alimentaire des entrées que vous aviez saisies :",
  "🍽 Открыть калории": "🍽 Ouvrir les calories",
  "🍽 Тренер {who} изменил(а) ваш дневник питания:": "🍽 Le coach {who} a modifié votre journal alimentaire :",
  "🎫 Абонемент в зал заканчивается через 4 дня — {date}. Самое время продлить 💪": "🎫 L'abonnement à la salle se termine dans 4 jours — {date}. C'est le moment idéal pour le renouveler 💪",
  "🎫 Завтра ({date}) последний день абонемента в зал. Не забудьте продлить!": "🎫 Demain ({date}), c'est le dernier jour de votre abonnement à la salle. N'oubliez pas de le renouveler !",
  "🎫 Обновить дату абонемента": "🎫 Mettre à jour la date d'abonnement",
  "🎯 Тренер {who} изменил(а) вашу норму питания: цель — <b>{goal}</b>, норма — <b>{target}</b>. Подробности в разделе «Калории».": "🎯 Le coach {who} a modifié votre objectif nutritionnel : objectif — <b>{goal}</b>, norme — <b>{target}</b>. Détails dans la section « Calories ».",
  "🏅 <b>Новые ачивки ({n}):</b>": "🏅 <b>Nouveaux succès ({n}) :</b>",
  "🏅 Ваш сертификат «{name}» подтверждён! Он уже в «Достижениях → Соревнования».": "🏅 Votre certificat « {name} » a été validé ! Il est déjà dans « Succès → Compétitions ».",
  "🏅 Новый сертификат на проверке от {who}: «{name}». Откройте Настройки → Админ-панель.": "🏅 Nouveau certificat en attente de validation de la part de {who} : « {name} ». Ouvrez Paramètres → Panneau d'administration.",
  "🏋️ {who} предлагает стать вашим тренером. Принять или отклонить можно в разделе «Участники».": "🏋️ {who} vous propose de devenir votre coach. Vous pouvez accepter ou refuser dans la section « Participants ».",
