  "Готово! ✅ Анкета сохранена.\nЯ буду присылать итоги тренировок, утренние напоминания о зарядке и иногда спрашивать про активность. Выключить напоминания — /reminders": "¡Listo! ✅ Cuestionario guardado.\nTe enviaré los resúmenes de entrenamientos, recordatorios matutinos para hacer ejercicios y a veces te preguntaré por tu actividad. Desactivar los recordatorios — /reminders",
