  "Доброе утро! Вращения плечами и наклоны в стороны — по 10–15 повторений в каждую сторону 💪": "¡Buenos días! Rotaciones de hombros e inclinaciones laterales — 10–15 repeticiones por lado 💪",
  "Доброе утро! Выпады — по 8 на каждую ногу. Спокойно, без рывков.": "¡Buenos días! Zancadas — 8 por pierna. Con calma, sin tirones.",
  "Доброе утро! Наклон вперёд: тянемся к носкам 20 секунд, колени мягкие.": "¡Buenos días! Flexión hacia adelante: llega hacia los pies durante 20 segundos, rodillas suaves.",
  "Доброе утро! Планка 30 секунд: живот подтянут, спина ровная ⏱": "¡Buenos días! Plancha 30 segundos: abdomen contraído, espalda recta ⏱",
