  "Кто может видеть ваши данные (возраст, пол, вес, рост, цель)?\nПо умолчанию — только вы. Изменить можно в приложении: Участники → вы → «Личные данные».": "¿Quién puede ver tus datos (edad, sexo, peso, altura, objetivo)?\nPor defecto, solo tú. Puedes cambiarlo en la app: Participantes → tú → «Datos personales».",
