  "🎫 Завтра ({date}) последний день абонемента в зал. Не забудьте продлить!": "🎫 Mañana ({date}) vence tu abono al gimnasio. ¡No olvides renovarlo!",
  "🎫 Обновить дату абонемента": "🎫 Actualizar fecha del abono",
