  "🏅 Ваш сертификат «{name}» подтверждён! Он уже в «Достижениях → Соревнования».": "🏅 ¡Tu certificado «{name}» fue confirmado! Ya está en «Logros → Competiciones».",
  "🏅 Новый сертификат на проверке от {who}: «{name}». Откройте Настройки → Админ-панель.": "🏅 Nuevo certificado en revisión de {who}: «{name}». Abre Ajustes → Panel de administrador.",
  "🏋️ {who} предлагает стать вашим тренером. Принять или отклонить можно в разделе «Участники».": "🏋️ {who} te propone ser tu entrenador. Puedes aceptar o rechazar en la sección «Participantes».",
