  "😤 НУ ДАВАЙ, ЗАПЛАЧЬ!!!\n\nТренировка на {p}% хуже обычного:": "😤 ¡VAMOS, LLORA!!!\n\nEntrenamiento un {p}% peor que lo habitual:",
  "😮‍💨 Тяжёлый рабочий день, нет сил": "😮‍💨 Día de trabajo pesado, sin energía",
