  "🎫 Абонемент в зал заканчивается через 4 дня — {date}. Самое время продлить 💪": "🎫 L'abbonamento in palestra scade tra 4 giorni — {date}. È il momento perfetto per rinnovarlo 💪",
  "🎫 Завтра ({date}) последний день абонемента в зал. Не забудьте продлить!": "🎫 Domani ({date}) è l'ultimo giorno del tuo abbonamento in palestra. Non dimenticare di rinnovarlo!",
  "🎫 Обновить дату абонемента": "🎫 Aggiorna la data dell'abbonamento",
  "🎯 Тренер {who} изменил(а) вашу норму питания: цель — <b>{goal}</b>, норма — <b>{target}</b>. Подробности в разделе «Калории».": "🎯 L'allenatore/trice {who} ha modificato il tuo fabbisogno alimentare: obiettivo — <b>{goal}</b>, fabbisogno — <b>{target}</b>. Dettagli nella sezione «Calorie».",
  "🏅 <b>Новые ачивки ({n}):</b>": "🏅 <b>Nuovi traguardi ({n}):</b>",
  "🏅 Ваш сертификат «{name}» подтверждён! Он уже в «Достижениях → Соревнования».": "🏅 Il tuo certificato «{name}» è stato confermato! È già in «Traguardi → Competizioni».",
  "🏅 Новый сертификат на проверке от {who}: «{name}». Откройте Настройки → Админ-панель.": "🏅 Nuovo certificato in verifica da {who}: «{name}». Apri Impostazioni → Pannello admin.",
  "🏋️ {who} предлагает стать вашим тренером. Принять или отклонить можно в разделе «Участники».": "🏋️ {who} propone di diventare il tuo allenatore. Puoi accettare o rifiutare nella sezione «Partecipanti».",
  "🏋️ Я и мой тренер": "🏋️ Io e il mio allenatore",
  "👀 Подопечный <b>{name}</b> завершил тренировку:": "👀 L'atleta <b>{name}</b> ha completato l'allenamento:",
  "👍 Да": "👍 Sì",
  "👎 Нет": "👎 No",
  "👥 Все мои участники": "👥 Tutti i miei partecipanti",
  "👨 Мужской": "👨 Maschio",
  "👩 Женский": "👩 Femmina",
  "👶 Дети / выгул собаки": "👶 Bambini / passeggiata col cane",
  "📅 Запланировать тренировку": "📅 Pianifica un allenamento",
  "📊 Открыть статистику": "📊 Apri le statistiche",
  "📊 Последние 7 дней: тренировок <b>{n}</b>, тоннаж <b>{ton} кг</b>{cardio}.\nПолные итоги придут в воскресенье, в конце месяца, квартала и года в 21:00.": "📊 Ultimi 7 giorni: allenamenti <b>{n}</b>, tonnellaggio <b>{ton} kg</b>{cardio}.\nI riepiloghi completi arriveranno di domenica, a fine mese, trimestre e anno alle 21:00.",
  "📒 Открыть дневник": "📒 Apri il diario",
  "📦 Переезд / закупки, таскал тяжёлое": "📦 Trasloco / spesa, ho portato cose pesanti",
  "📨 {who} хочет добавить вас в участники. Ответьте в разделе «Участники».": "📨 {who} vuole aggiungerti come partecipante. Rispondi nella sezione «Partecipanti».",
