  "😤 НУ ДАВАЙ, ЗАПЛАЧЬ!!!\n\nТренировка на {p}% хуже обычного:": "😤 DAI, PIANGI PURE!!!\n\nAllenamento del {p}% peggiore del solito:",
  "😮‍💨 Тяжёлый рабочий день, нет сил": "😮‍💨 Giornata di lavoro pesante, niente energie",
