  "Готово! ✅ Анкета сохранена.\nЯ буду присылать итоги тренировок, утренние напоминания о зарядке и иногда спрашивать про активность. Выключить напоминания — /reminders": "Tayyor! ✅ Anketa saqlandi.\nMen mashgʻulot natijalarini, ertalabki badantarbiya eslatmalarini yuborib turaman va ba’zan faolligingiz haqida soʻrayman. Eslatmalarni oʻchirish — /reminders",
