  "Дисциплина побеждает мотивацию. Надень кроссовки — остальное приложится 👟": "Intizom motivatsiyadan ustun. Krossovkangni kiy — qolgani oʻz-oʻzidan boʻladi 👟",
  "Дневник тренировок — в приложении 👇": "Mashgʻulotlar kundaligi — ilovada 👇",
