  "Доброе утро! Вращения плечами и наклоны в стороны — по 10–15 повторений в каждую сторону 💪": "Xayrli tong! Yelkalarni aylantirish va yon tomonlarga egilish — har tomonga 10–15 martadan 💪",
  "Доброе утро! Выпады — по 8 на каждую ногу. Спокойно, без рывков.": "Xayrli tong! Hamlalar — har oyoqqa 8 tadan. Xotirjam, siltanmasdan.",
  "Доброе утро! Наклон вперёд: тянемся к носкам 20 секунд, колени мягкие.": "Xayrli tong! Oldinga egilish: 20 soniya oyoq uchlariga choʻziling, tizzalar yumshoq.",
  "Доброе утро! Планка 30 секунд: живот подтянут, спина ровная ⏱": "Xayrli tong! 30 soniya planka: qorin tortilgan, bel tekis ⏱",
  "Доброе утро! Шаг на месте 1 минуту, колени высоко — разгоняем пульс 👟": "Xayrli tong! 1 daqiqa joyida qadam tashlang, tizzalar baland — pulsni tezlashtiramiz 👟",
  "Доброе утро! ☀️ Потянись: руки вверх и 5 глубоких вдохов — тело просыпается.": "Xayrli tong! ☀️ Kerishing: qoʻllar yuqoriga va 5 ta chuqur nafas — tana uygʻonmoqda.",
  "Другое": "Boshqa",
  "Жим гантелей на наклонной": "Qiya skameykada gantel siqish",
  "Жим гантелей сидя": "Oʻtirib gantel siqish",
  "Жим лёжа": "Yotib shtanga siqish",
  "Жим ногами": "Oyoq bilan siqish",
