  "Жиры": "Yogʻlar",
  "За период ни одной тренировки. Самое время вернуться 💪": "Bu davrda birorta ham mashgʻulot boʻlmadi. Qaytish vaqti keldi 💪",
  "За что:": "Nima uchun:",
  "Завтрак": "Nonushta",
  "Задний вис": "Orqa osilish (back lever)",
  "Записал! Любое движение — в копилку 👍": "Yozib qoʻydim! Har qanday harakat — foydali 👍",
  "Записал: {n} шагов 👍": "Yozib qoʻydim: {n} qadam 👍",
  "Заполните возраст, пол, рост и вес в личных данных — я посчитаю вашу норму и подскажу, всё ли в порядке.": "Shaxsiy ma’lumotlarda yosh, jins, boʻy va vaznni toʻldiring — me’yoringizni hisoblab, hammasi joyidami, aytib beraman.",
  "Здоровье и тонус": "Salomatlik va tonus",
  "Икры": "Boldir",
  "Икры стоя": "Tik turib boldir koʻtarish",
  "Итоги {q}-го квартала": "{q}-chorak yakunlari",
  "Итоги {y} года": "{y}-yil yakunlari",
  "Итоги месяца": "Oy yakunlari",
  "Итоги недели": "Hafta yakunlari",
  "Какая у вас цель занятий?": "Mashgʻulotlardan maqsadingiz nima?",
  "Кардио: <b>{v} км</b>": "Kardio: <b>{v} km</b>",
  "Квадрицепс": "Kvadriseps",
  "Колено к груди лёжа": "Yotib tizzani koʻkrakka tortish",
  "Кошка-корова 10–15 плавных повторов — спина будет благодарна весь день 🐱🐮": "«Mushuk-sigir» mashqini 10–15 marta ravon takrorlang — belingiz kun boʻyi minnatdor boʻladi 🐱🐮",
  "Кто может видеть ваши данные (возраст, пол, вес, рост, цель)?\nПо умолчанию — только вы. Изменить можно в приложении: Участники → вы → «Личные данные».": "Ma’lumotlaringizni (yosh, jins, vazn, boʻy, maqsad) kim koʻra oladi?\nStandart holatda — faqat siz. Ilovada oʻzgartirish mumkin: Ishtirokchilar → siz → «Shaxsiy ma’lumotlar».",
  "Лучшая тренировка — та, которая состоялась. Даже лёгкая. Погнали? 🔥": "Eng yaxshi mashgʻulot — boʻlib oʻtgan mashgʻulot. Hatto yengil boʻlsa ham. Ketdikmi? 🔥",
  "Лучшая тренировка: {name} {date} — {v} кг": "Eng yaxshi mashgʻulot: {name} {date} — {v} kg",
  "Махи гантелями в стороны": "Gantellarni yonga koʻtarish",
  "Можно загрузить заново.": "Qayta yuklash mumkin.",
  "Молотки": "Bolgʻacha (hammer)",
  "Набрать мышечную массу": "Mushak massasini oshirish",
  "Наклон к ногам": "Oyoqlarga egilish",
  "Напишите вес в килограммах, например: 72.5": "Vazningizni kilogrammda yozing, masalan: 72.5",
  "Напишите возраст числом, например: 29": "Yoshingizni raqam bilan yozing, masalan: 29",
  "Напишите количество шагов числом, например: 12000": "Qadamlar sonini raqam bilan yozing, masalan: 12000",
  "Напишите рост в сантиметрах, например: 178": "Boʻyingizni santimetrda yozing, masalan: 178",
  "Напишите свою цель в паре слов.": "Maqsadingizni bir-ikki soʻz bilan yozing.",
  "Не залипай в телефон — вставай! Шаг на месте 1 минуту, колени высоко.": "Telefonga yopishib qolma — tur! 1 daqiqa joyida qadam, tizzalar baland.",
  "Небольшая цель на сегодня: 15 минут движения. Справишься? Уверен, что да!": "Bugungi kichik maqsad: 15 daqiqa harakat. Uddalaysanmi? Ishonaman, uddalaysan!",
  "Негативные подтягивания": "Negativ tortilish",
  "Обед": "Tushlik",
  "Обратные отжимания от скамьи": "Skameykadan teskari itarilish",
  "Опишите цель в паре слов.": "Maqsadingizni bir-ikki soʻz bilan tasvirlang.",
  "Отжимания": "Yerdan itarilish",
