  "Перекусы": "Tamaddilar",
  "Перерыв — это нормально. Возвращение — это сила. Жду твою следующую тренировку 💪": "Tanaffus — bu normal. Qaytish — bu kuch. Keyingi mashgʻulotingni kutaman 💪",
