  "Подходов: <b>{n}</b>": "Yondashuvlar: <b>{n}</b>",
  "Подходы не заполнены": "Yondashuvlar toʻldirilmagan",
  "Подъём гантелей перед собой": "Gantellarni oldinga koʻtarish",
  "Подъём ног в висе": "Osilib oyoq koʻtarish",
  "Подъём переворотом": "Turnikda aylanib chiqish",
  "Подъём штанги на бицепс": "Bitsepsga shtanga koʻtarish",
  "Подъём! 30 «джампинг-джеков» — и кровь побежала быстрее 🔥": "Turing! 30 ta «jumping jack» — va qon tezroq yugura boshlaydi 🔥",
  "Помнишь, зачем ты начинал? Один шаг — одна тренировка. Сегодня отличный день, чтобы вернуться!": "Nima uchun boshlaganingni eslaysanmi? Bir qadam — bitta mashgʻulot. Bugun qaytish uchun ajoyib kun!",
  "Понял. Отдых тоже часть прогресса 😌 Завтра — новый день!": "Tushundim. Dam olish ham rivojlanishning bir qismi 😌 Ertaga — yangi kun!",
  "Похудеть": "Ozish",
  "Предплечья": "Bilak",
  "Пресс": "Press",
  "Привет, {name}! 👋 Я бот «ТренДневника».\nЗадам 6 коротких вопросов — это займёт минуту. Эти данные видите только вы, пока сами не решите иначе.": "Salom, {name}! 👋 Men «GymDiary» botiman.\n6 ta qisqa savol beraman — bu bir daqiqa oladi. Bu ma’lumotlarni oʻzingiz boshqacha qaror qilmaguningizcha faqat siz koʻrasiz.",
  "Присед со штангой": "Shtanga bilan oʻtirib-turish",
  "Приседания (свой вес)": "Oʻtirib-turish (oʻz vazni)",
  "Причина: {v}.": "Sabab: {v}.",
  "Прогресс есть — так держать! 🔥": "Rivojlanish bor — shunday davom eting! 🔥",
  "Прогресс любит регулярность. Два дня отдыха были, пора снова в бой 🏋️": "Rivojlanish muntazamlikni yaxshi koʻradi. Ikki kun dam olding, endi yana jangga 🏋️",
  "Прыжки на скакалке": "Arqonda sakrash",
  "Разведение гантелей": "Gantellarni yonga yoyish",
  "Разгибание ног": "Oyoqlarni yozish",
  "Растяжка икр у стены": "Devor yonida boldirni choʻzish",
  "Растяжка общая": "Umumiy choʻzilish",
  "Растяжка плеч": "Yelkalarni choʻzish",
  "Румынская тяга": "Rumincha tortish",
  "Русская фраза {x}": "Oʻzbekcha ibora {x}",
  "Рывок штанги": "Shtangani siltab koʻtarish",
  "С возвращением, {name}! Записывайте тренировки в дневнике 👇\n\n/profile — заново заполнить анкету\n/reminders — вкл/выкл напоминания": "Yana xush kelibsiz, {name}! Mashgʻulotlarni kundalikka yozib boring 👇\n\n/profile — anketani qaytadan toʻldirish\n/reminders — eslatmalarni yoqish/oʻchirish",
  "Самочувствие: {v}": "Oʻzini his qilish: {v}",
  "Сгибание ног": "Oyoqlarni bukish",
  "Сегодня тренировки не было. Была ли какая-то физическая активность за день?": "Bugun mashgʻulot boʻlmadi. Kun davomida biror jismoniy faollik boʻldimi?",
  "Сертификат «{name}» отклонён.": "«{name}» sertifikati rad etildi.",
  "Скакалка": "Arqon",
  "Сколько вам лет? Напишите число.": "Yoshingiz nechada? Raqam bilan yozing.",
  "Сколько шагов прошли за день?": "Bugun necha qadam yurdingiz?",
  "Скручивания": "Qorin uchun buralish",
  "Следующая — злее. 💪": "Keyingisi — shiddatliroq. 💪",
  "Следующий период — сильнее. 💪": "Keyingi davr — yanada kuchliroq. 💪",
  "Спина": "Orqa",
  "Становая тяга": "Stanovoy tortish",
  "Стать сильнее": "Kuchliroq boʻlish",
  "Степпер": "Stepper",
  "Стойка на руках": "Qoʻlda tik turish",
  "Съедено: <b>{v} ккал</b>": "Yeyildi: <b>{v} kkal</b>",
  "Съедено: <b>{v} ккал</b> из {norm} ({p}%)": "Yeyildi: <b>{v} kkal</b>, me’yor {norm} ({p}%)",
  "Твой будущий «я» скажет спасибо за сегодняшнюю тренировку. Не подводи его!": "Kelajakdagi «men»ing bugungi mashgʻulot uchun rahmat aytadi. Uni ranjitma!",
