  "Тяга штанги в наклоне": "Egilib shtanga tortish",
  "Тяга штанги к подбородку": "Shtangani iyakka tortish",
  "Углеводы": "Uglevodlar",
  "Уголок": "Burchak (L-sit)",
  "Уже несколько дней без тренировки. Мышцы скучают — даже 20 минут сегодня лучше, чем ничего 💪": "Bir necha kundan beri mashgʻulot yoʻq. Mushaklar sogʻindi — bugun hatto 20 daqiqa ham hech narsadan yaxshiroq 💪",
  "Ужин": "Kechki ovqat",
  "Упражнение": "Mashq",
  "Утренний комплекс на 5 минут: потянись, плечи, наклоны, приседания, прыжки, выпады, планка, наклон вперёд, кошка-корова, шаг на месте ✅": "5 daqiqalik ertalabki kompleks: kerishish, yelkalar, egilishlar, oʻtirib-turish, sakrashlar, hamlalar, planka, oldinga egilish, mushuk-sigir, joyida qadam ✅",
  "Участник": "Ishtirokchi",
  "Флажок": "Bayroq (human flag)",
  "Форма не уходит за пару дней, но привычка — уходит. Запланируй тренировку прямо сейчас 📅": "Sport formasi bir-ikki kunda yoʻqolmaydi, lekin odat yoʻqoladi. Mashgʻulotni hoziroq rejalashtir 📅",
