  "Готово! ✅ Анкета сохранена.\nЯ буду присылать итоги тренировок, утренние напоминания о зарядке и иногда спрашивать про активность. Выключить напоминания — /reminders": "Tamamdır! ✅ Anket kaydedildi.\nAntrenman özetlerini, sabah egzersiz hatırlatıcılarını göndereceğim ve bazen aktiviteni soracağım. Hatırlatıcıları kapatmak için — /reminders",
