  "Дисциплина побеждает мотивацию. Надень кроссовки — остальное приложится 👟": "Disiplin motivasyonu yener. Ayakkabılarını giy — gerisi kendiliğinden gelir 👟",
  "Дневник тренировок — в приложении 👇": "Antrenman günlüğü — uygulamada 👇",
