  "Добавьте белка.": "Protein ekleyin.",
  "Доброе утро! Вращения плечами и наклоны в стороны — по 10–15 повторений в каждую сторону 💪": "Günaydın! Omuz çevirme ve yana eğilmeler — her yöne 10–15 tekrar 💪",
  "Доброе утро! Выпады — по 8 на каждую ногу. Спокойно, без рывков.": "Günaydın! Lunge — her bacağa 8 tekrar. Sakin, ani hareket yapmadan.",
  "Доброе утро! Наклон вперёд: тянемся к носкам 20 секунд, колени мягкие.": "Günaydın! Öne eğilme: 20 saniye ayak parmaklarına uzan, dizler hafif bükük.",
  "Доброе утро! Планка 30 секунд: живот подтянут, спина ровная ⏱": "Günaydın! 30 saniye plank: karın sıkı, sırt düz ⏱",
  "Доброе утро! Шаг на месте 1 минуту, колени высоко — разгоняем пульс 👟": "Günaydın! 1 dakika yerinde adım, dizler yukarı — nabzı hızlandırıyoruz 👟",
  "Доброе утро! ☀️ Потянись: руки вверх и 5 глубоких вдохов — тело просыпается.": "Günaydın! ☀️ Gerin: kollar yukarı ve 5 derin nefes — vücut uyanıyor.",
