  "Кто может видеть ваши данные (возраст, пол, вес, рост, цель)?\nПо умолчанию — только вы. Изменить можно в приложении: Участники → вы → «Личные данные».": "Verilerinizi (yaş, cinsiyet, kilo, boy, hedef) kim görebilir?\nVarsayılan olarak — yalnızca siz. Uygulamada değiştirebilirsiniz: Katılımcılar → siz → «Kişisel veriler».",
