  "🏅 Новый сертификат на проверке от {who}: «{name}». Откройте Настройки → Админ-панель.": "🏅 {who} kullanıcısından incelemede yeni bir sertifika var: «{name}». Ayarlar → Yönetici paneli'ni açın.",
  "🏋️ {who} предлагает стать вашим тренером. Принять или отклонить можно в разделе «Участники».": "🏋️ {who} antrenörünüz olmayı teklif ediyor. «Katılımcılar» bölümünden kabul veya reddedebilirsiniz.",
