  "Готово! ✅ Анкета сохранена.\nЯ буду присылать итоги тренировок, утренние напоминания о зарядке и иногда спрашивать про активность. Выключить напоминания — /reminders": "完成！✅ 问卷已保存。\n我会发送训练总结和晨练提醒，偶尔也会问问你的活动情况。关闭提醒 — /reminders",
