  "Готово! ✅ Анкета сохранена.\nЯ буду присылать итоги тренировок, утренние напоминания о зарядке и иногда спрашивать про активность. Выключить напоминания — /reminders": "完了！✅ プロフィールを保存しました。\nトレーニングのまとめや朝のストレッチのリマインダーを送ったり、ときどき活動について質問したりします。リマインダーをオフにするには — /reminders",
