  "Доброе утро! Выпады — по 8 на каждую ногу. Спокойно, без рывков.": "おはようございます！ランジ — 片脚8回ずつ。反動をつけず、ゆっくりと。",
  "Доброе утро! Наклон вперёд: тянемся к носкам 20 секунд, колени мягкие.": "おはようございます！前屈：膝をゆるめて、つま先に向かって20秒伸ばそう。",
  "Доброе утро! Планка 30 секунд: живот подтянут, спина ровная ⏱": "おはようございます！プランク30秒：お腹を引き締めて、背中はまっすぐ ⏱",
