  "Кто может видеть ваши данные (возраст, пол, вес, рост, цель)?\nПо умолчанию — только вы. Изменить можно в приложении: Участники → вы → «Личные данные».": "あなたのデータ（年齢、性別、体重、身長、目標）を見られるのは誰にしますか？\nデフォルトではあなただけです。アプリの「メンバー」→ あなた →「個人データ」でいつでも変更できます。",
  "Лучшая тренировка — та, которая состоялась. Даже лёгкая. Погнали? 🔥": "最高のトレーニングは、実際にやったトレーニング。軽めでもOK。行こう！🔥",
