  "Выход силой на одну руку": "원암 머슬업",
  "Готово! ✅ Анкета сохранена.\nЯ буду присылать итоги тренировок, утренние напоминания о зарядке и иногда спрашивать про активность. Выключить напоминания — /reminders": "완료! ✅ 설문이 저장되었어요.\n운동 결과와 아침 스트레칭 알림을 보내드리고, 가끔 활동에 대해 물어볼게요. 알림을 끄려면 — /reminders",
  "Гребля": "로잉",
  "Грудь": "가슴",
  "Дисциплина побеждает мотивацию. Надень кроссовки — остальное приложится 👟": "동기부여보다 꾸준함이 이겨요. 운동화만 신으면 나머지는 따라와요 👟",
