  "Дней с записями: <b>{n}</b>": "기록한 날: <b>{n}</b>일",
  "Добавьте белка.": "단백질을 더 추가하세요.",
  "Доброе утро! Вращения плечами и наклоны в стороны — по 10–15 повторений в каждую сторону 💪": "좋은 아침이에요! 어깨 돌리기와 옆으로 굽히기 — 양쪽 각각 10~15회 💪",
  "Доброе утро! Выпады — по 8 на каждую ногу. Спокойно, без рывков.": "좋은 아침이에요! 런지 — 양쪽 다리 각각 8회. 천천히, 무리하지 마세요.",
  "Доброе утро! Наклон вперёд: тянемся к носкам 20 секунд, колени мягкие.": "좋은 아침이에요! 앞으로 숙이기: 20초 동안 발끝을 향해 뻗고, 무릎은 살짝 굽히세요.",
  "Доброе утро! Планка 30 секунд: живот подтянут, спина ровная ⏱": "좋은 아침이에요! 플랭크 30초: 배에 힘을 주고 등을 곧게 펴세요 ⏱",
  "Доброе утро! Шаг на месте 1 минуту, колени высоко — разгоняем пульс 👟": "좋은 아침이에요! 제자리걸음 1분, 무릎을 높이 — 심박수를 올려요 👟",
