  "Кто может видеть ваши данные (возраст, пол, вес, рост, цель)?\nПо умолчанию — только вы. Изменить можно в приложении: Участники → вы → «Личные данные».": "내 정보(나이, 성별, 체중, 키, 목표)를 누가 볼 수 있나요?\n기본적으로는 본인만 볼 수 있어요. 앱에서 변경할 수 있어요: 참가자 → 나 → «개인 정보».",
  "Лучшая тренировка — та, которая состоялась. Даже лёгкая. Погнали? 🔥": "가장 좋은 운동은 실제로 하는 운동이에요. 가볍더라도요. 시작해볼까요? 🔥",
