  "⚠️ Секрет MINI_APP_URL не задан — боту неоткуда брать картинки.": "⚠️ MINI_APP_URL 시크릿이 설정되지 않았어요 — 봇이 이미지를 가져올 곳이 없어요.",
  "⚽ Игры, танцы, спорт с друзьями": "⚽ 게임, 춤, 친구들과 스포츠",
  "✅ {who} принял(а) вас как тренера. Его (её) тренировки теперь в вашем календаре.": "✅ {who}님이 회원님을 트레이너로 받아들였어요. 이제 그(그녀)의 운동이 회원님의 캘린더에 표시돼요.",
